analyze.mjs.text:
// Classifies the result of two HTTP probes (real requests collected by
// probe.mjs, or pasted in by hand) into a verdict on whether a site's `.git`
// directory is publicly exposed.
//
// Pure function, no I/O, no network -- this is the module both the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can only ever analyse a payload someone already fetched) import, so
// the classification logic exists exactly once.
//
// The value here isn't "did /.git/HEAD return 200" -- curl does that, and a
// bare status check is wrong on any server that answers every unknown path
// with 200 (a "soft 404" error page, common on shared hosting and several
// popular static-site setups). It's checking that the response BODY parses
// as real git-internal content:
//
//   * `.git/HEAD` in a real repository is a one-line file, either
//     `ref: refs/heads/<branch>\n` (the normal case) or a bare 40-character
//     hex SHA-1 (a detached HEAD). Nothing else a webserver would plausibly
//     serve at that path looks like this.
//   * `.git/config` in a real repository contains an INI-style `[core]`
//     section -- every git repository's config starts with one, written by
//     `git init`.
//
// Either one alone, matched against its exact expected shape, is strong
// evidence of real exposure (not a coincidence -- see the regexes' comments
// for how narrow they are). Both matching is the same finding stated with
// higher confidence, since a real exposed `.git` directory normally serves
// every file inside it identically.
//
// What this does NOT do, on purpose: it never requests `.git/index`,
// `.git/logs/HEAD`, or any packed object -- those can be considerably larger
// and reading them would start to look like downloading the repository
// rather than checking whether it is exposed. If HEAD or config is exposed,
// the rest almost always is too; naming that inference in the report is
// enough to make the point without this tool doing the actual bulk read
// itself (`git-dumper`/`GitTools`, named in the report text, are the tools
// an authorised owner would reach for to quantify the exposure fully).

// `ref: refs/heads/main` / `ref: refs/heads/feature/x` -- a ref name is a
// sequence of non-whitespace, non-control characters per git's own
// check-ref-format rules; this accepts anything printable rather than
// re-implementing that full grammar, since the goal is distinguishing real
// git content from an arbitrary error page, not validating a ref name.
const HEAD_SYMBOLIC_RE = /^ref:\s+refs\/\S+$/;
// A detached HEAD: a bare 40-character (SHA-1) hex commit id, nothing else
// on the line.
const HEAD_DETACHED_RE = /^[0-9a-f]{40}$/i;
// Every `git init`-created config file opens with a `[core]` section before
// anything else -- distinctive enough on its own that no ordinary web page
// or error page would happen to contain it verbatim.
const CONFIG_CORE_RE = /\[core\]/;

function normaliseLine(sample) {
  return typeof sample === 'string' ? sample.trim() : '';
}

/** True when `bodySample` is exactly what a real `.git/HEAD` file contains. */
export function looksLikeGitHead(bodySample) {
  const line = normaliseLine(bodySample);
  return HEAD_SYMBOLIC_RE.test(line) || HEAD_DETACHED_RE.test(line);
}

/** True when `bodySample` contains the `[core]` section every real
 * `.git/config` file opens with. */
export function looksLikeGitConfig(bodySample) {
  return CONFIG_CORE_RE.test(typeof bodySample === 'string' ? bodySample : '');
}

function probeSummary(probe) {
  const p = probe && typeof probe === 'object' ? probe : { ok: false };
  return {
    ok: p.ok !== false,
    status: p.status ?? null,
    url: p.url ?? null,
    bodySample: typeof p.bodySample === 'string' ? p.bodySample : '',
    truncated: !!p.truncated,
    error: p.error ?? null,
  };
}

/**
 * @param {string} target - the URL that was probed (for display only)
 * @param {{head: object, config: object}} probe - the two raw probe results
 *   `runProbe` (or a hand-built equivalent) produced
 * @returns {{target: string, head: object, config: object, findings: object[],
 *   dangerCount: number, ok: boolean, incomplete: boolean}}
 */
export function buildReport(target, probe) {
  const p = probe && typeof probe === 'object' ? probe : {};
  const head = probeSummary(p.head);
  const config = probeSummary(p.config);
  const incomplete = !head.ok && !config.ok;
  const findings = [];

  if (!incomplete) {
    const headExposed = head.ok && head.status === 200 && looksLikeGitHead(head.bodySample);
    const configExposed = config.ok && config.status === 200 && looksLikeGitConfig(config.bodySample);

    if (headExposed && configExposed) {
      findings.push({
        id: 'git-directory-exposed',
        severity: 'danger',
        title: 'The .git directory is publicly readable',
        detail:
          'Both .git/HEAD and .git/config responded with real git-internal content, not a ' +
          "generic error page -- this is not a coincidence: HEAD parsed as a git ref (\"ref: " +
          'refs/heads/…\" or a bare commit SHA) and config contained the [core] section every ' +
          'real repository opens with. This lets anyone reconstruct the entire committed source ' +
          'history -- including files and secrets that were removed in a later commit, which a ' +
          'live directory listing would never show -- using a public tool such as git-dumper or ' +
          'GitTools. Remove the .git directory from the deployed webroot (it should never be ' +
          'served at all) or block the path at the webserver/CDN.',
        evidenceUrl: head.url,
      });
    } else if (headExposed) {
      findings.push({
        id: 'git-head-exposed',
        severity: 'danger',
        title: '.git/HEAD is publicly readable',
        detail:
          `The response body (\"${head.bodySample.trim()}\") is exactly what a real .git/HEAD ` +
          'file contains, not a generic error page. .git/config did not confirm it independently ' +
          '(different status, or content that did not match a real config file), but HEAD alone ' +
          'is real git-internal content and should not be reachable -- treat this the same as full ' +
          'exposure and verify with an authorised tool such as git-dumper or GitTools.',
        evidenceUrl: head.url,
      });
    } else if (configExposed) {
      findings.push({
        id: 'git-config-exposed',
        severity: 'danger',
        title: '.git/config is publicly readable',
        detail:
          'The response body contains a real git config [core] section, not a generic error page. ' +
          '.git/HEAD did not confirm it independently, but an exposed config file on its own can ' +
          'leak remote URLs (sometimes with embedded credentials or CI tokens) and confirms the ' +
          '.git directory is reachable -- treat this as exposure and verify with an authorised ' +
          'tool such as git-dumper or GitTools.',
        evidenceUrl: config.url,
      });
    }
    // else: neither response matched real git content -- protected (a 403,
    // a 404, a redirect, or a "soft 404" page that answers every path with
    // 200 but generic content). No finding.
  }

  const dangerCount = findings.filter((f) => f.severity === 'danger').length;

  return {
    target,
    head,
    config,
    findings,
    dangerCount,
    ok: !incomplete && dangerCount === 0,
    incomplete,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends two real GET requests to a site you name -- .git/HEAD and
// .git/config, resolved relative to the URL you pass -- and reports whether
// the response bodies are real git-internal content (a publicly exposed
// .git directory) rather than a generic error page. Your machine, your
// network -- no request goes through this portfolio or anywhere but the
// target site.
//
//   node check.mjs <url> [--json] [--timeout <ms>]
//
// Pass the site root (e.g. https://example.com/) unless you specifically
// want to check a subpath's own .git directory, in which case pass that
// subpath with a trailing slash (e.g. https://example.com/app/) -- the two
// probed paths are resolved relative to whatever URL you give, the same way
// a browser resolves a relative link.
//
// Only point this at a system you own or are authorised to test. This
// sends two ordinary, unauthenticated GET requests -- nothing here bypasses
// authentication, reads protected data beyond what the target already
// serves to any anonymous visitor, or does anything a browser wouldn't also
// do by visiting the URL -- but treat it the same as you would curl or any
// other request tool aimed at someone else's server.
//
// Exit code 0 when both probes completed and no exposure finding is
// present; 1 when a finding is present or neither probe could complete
// (network error, timeout, bad URL).

import { runProbe } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  if (report.incomplete) {
    lines.push(`Both requests failed: HEAD: ${report.head.error} · config: ${report.config.error}`);
    lines.push('');
    lines.push('Neither probe completed -- re-run once the target is reachable.');
    return lines.join('\n');
  }
  lines.push(`  ${report.head.url ?? '(HEAD not requested)'}  ->  status ${report.head.status ?? '(request failed: ' + report.head.error + ')'}`);
  lines.push(`  ${report.config.url ?? '(config not requested)'}  ->  status ${report.config.status ?? '(request failed: ' + report.config.error + ')'}`);
  lines.push('');

  if (report.findings.length === 0) {
    lines.push('Neither .git/HEAD nor .git/config returned real git-internal content.');
    lines.push('The .git directory does not appear to be publicly exposed.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`   ${f.detail}`);
      lines.push(`   evidence: ${f.evidenceUrl}`);
      lines.push('');
    }
  }

  lines.push(
    'This is evidence from these two responses, not a full security assessment -- ' +
      'see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const args = { target: null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (!args.target && !argv[i].startsWith('--')) args.target = argv[i];
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(target, { probeFn = runProbe, timeoutMs } = {}) {
  const probe = await probeFn(target, timeoutMs ? { timeoutMs } : {});
  return buildReport(target, probe);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.target) {
    console.error('Usage: node check.mjs <url> [--json] [--timeout <ms>]');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.target);
  } catch {
    console.error(`Not a valid URL: ${args.target}`);
    process.exit(2);
  }

  const report = await runCheck(args.target, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify({ target: report.target, head: report.head, config: report.config }, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Sends the real HTTP requests this check depends on: two GET requests to a
// target site -- one for `.git/HEAD`, one for `.git/config` -- resolved
// relative to the URL a caller passes in. Node's built-in http/https clients
// are used, and no redirect is followed automatically: a 3xx response is
// reported as-is, with its own status, rather than silently chasing the
// Location, so a caller always knows exactly which response the report
// describes.
//
// Unlike the header-only probes in this portfolio's sibling checkers
// (security-headers-check, cors-misconfig-check, cache-control-check), this
// one has to read a slice of the response *body*: whether `.git/HEAD` is
// really exposed is decided by whether its content parses as a git ref, not
// by the status code alone -- a status-code-only check is fooled by any
// server that answers every path with 200 (a "soft 404"), which is common
// enough that naive git-exposure scanners built on `curl -I` or a bare
// status check produce false positives on exactly this pattern.
//
// The body read is capped at BODY_CAP_BYTES and the socket is destroyed once
// that many bytes have arrived, so pointing this at a server that serves a
// huge file at a probed path costs a bounded amount of memory and time
// rather than downloading the whole thing -- both files this check reads are
// normally under 200 bytes in a real git checkout.
//
// This module only ever talks to the one target site a caller names. It
// makes no other network call, reads no local files, and sends nothing
// anywhere else.

import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';

const DEFAULT_TIMEOUT_MS = 10_000;
const BODY_CAP_BYTES = 8192;
const USER_AGENT =
  'git-exposure-check/1 (+https://duncan-haywood.github.io/monorepo-projects/git-exposure-check/)';

/** The two paths this check probes, relative to the base URL a caller gives
 * it. Exported so the CLI and tests can name them without repeating the
 * literal strings. */
export const HEAD_RELATIVE_PATH = '.git/HEAD';
export const CONFIG_RELATIVE_PATH = '.git/config';

/**
 * One GET request to `relativePath` resolved against `baseUrl`. Resolves
 * rather than rejects on any failure so a caller running several of these
 * never needs a try/catch per probe.
 *
 * @returns {Promise<{ok: boolean, status: number|null, protocol: string|null,
 *   url: string|null, bodySample: string, truncated: boolean, error: string|null}>}
 */
export function sendProbe(baseUrl, relativePath, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(relativePath, baseUrl);
    } catch (err) {
      resolve({ ok: false, status: null, protocol: null, url: null, bodySample: '', truncated: false, error: `invalid URL: ${err.message}` });
      return;
    }
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      resolve({ ok: false, status: null, protocol: null, url: parsed.href, bodySample: '', truncated: false, error: `unsupported scheme: ${parsed.protocol}` });
      return;
    }

    const requester = parsed.protocol === 'https:' ? httpsRequest : httpRequest;
    const headers = { 'user-agent': USER_AGENT, accept: '*/*' };

    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    const req = requester(
      parsed,
      { method: 'GET', headers, timeout: timeoutMs },
      (res) => {
        let bytes = Buffer.alloc(0);
        let truncated = false;
        res.on('data', (chunk) => {
          if (bytes.length >= BODY_CAP_BYTES) {
            truncated = true;
            return;
          }
          bytes = Buffer.concat([bytes, chunk]).subarray(0, BODY_CAP_BYTES);
          if (bytes.length >= BODY_CAP_BYTES) {
            truncated = true;
            res.destroy(); // stop reading once the cap is reached
          }
        });
        res.on('end', () => {
          finish({
            ok: true,
            status: res.statusCode ?? null,
            protocol: parsed.protocol,
            url: parsed.href,
            bodySample: bytes.toString('utf8'),
            truncated,
            error: null,
          });
        });
        res.on('close', () => {
          // `res.destroy()` above (hitting the cap) fires 'close' instead of
          // 'end' -- still a completed, successful read of everything up to
          // the cap, so this must resolve ok:true too, not read as a failure.
          finish({
            ok: true,
            status: res.statusCode ?? null,
            protocol: parsed.protocol,
            url: parsed.href,
            bodySample: bytes.toString('utf8'),
            truncated,
            error: null,
          });
        });
        res.on('error', (err) => finish({ ok: false, status: res.statusCode ?? null, protocol: parsed.protocol, url: parsed.href, bodySample: '', truncated: false, error: err.message }));
      },
    );
    req.on('timeout', () => req.destroy(new Error('timed out')));
    req.on('error', (err) => finish({ ok: false, status: null, protocol: parsed.protocol, url: parsed.href, bodySample: '', truncated: false, error: err.message }));
    req.end();
  });
}

/** Runs both probes against `targetUrl` (resolved as a base for the two
 * relative paths) and returns the raw results, same shape `analyze.mjs`'s
 * `buildReport` expects. */
export async function runProbe(targetUrl, opts = {}) {
  const [head, config] = await Promise.all([
    sendProbe(targetUrl, HEAD_RELATIVE_PATH, opts),
    sendProbe(targetUrl, CONFIG_RELATIVE_PATH, opts),
  ]);
  return { target: targetUrl, head, config };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL, the pasted probe JSON, or anything about what was checked --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'git-exposure-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
